#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# ── helpers for the stages below ──────────────────────────────────────────

die() { printf '\n  %s✗ %s%s\n\n' "$YELLOW" "$1" "$RESET"; exit 1; }

# flush_stdin discards keystrokes still buffered (e.g. the newline a paste leaves behind), so a
# stray Enter is not read as "no" by the next y/N question.
flush_stdin() { local _junk; while read -r -t 1 -n 10000 _junk; do :; done; }

# eu_dsn DSN succeeds for an https DSN on a *.de.sentry.io host (EU data residency).
eu_dsn() { [[ "$1" =~ ^https://[^@/\ ]+@[^/\ ]*\.de\.sentry\.io/[0-9]+$ ]]; }

# wait_for_health URL waits up to ~3 minutes for GET URL/health to answer 200.
wait_for_health() {
  local url="$1" i
  for i in $(seq 1 18); do
    [[ "$(curl -s -o /dev/null -w '%{http_code}' "$url/health" || true)" == 200 ]] && return 0
    note "waiting for $url/health ($i/18)"
    sleep 10
  done
  return 1
}

run_wizard() {

TOTAL_STAGES=5

banner "Stamina ops: Sentry, first release, UptimeRobot, Brevo"
command -v gh >/dev/null 2>&1 || die "gh is not installed (brew install gh)."
gh auth status >/dev/null 2>&1 || die "gh is not signed in (gh auth login)."
note "Skipped on purpose: Cloudflare R2 (backups + OpenTofu state). Those boxes of ticket 02 stay open."

# ── 1. Sentry ─────────────────────────────────────────────────────────────
stage "Sentry (EU region): one project for the web app, one for the API"
open_url "https://de.sentry.io/signup/"
step "Sign up or sign in on de.sentry.io. The address must end in de.sentry.io (EU data storage)."
step "Create an organization if asked (any name)."
step "Create project 1: Projects → Create Project. Platform: Vue. Name: stamina-web."
step "On its page open Settings → Client Keys (DSN) and copy the DSN."
ask SENTRY_DSN_WEB "Paste the stamina-web DSN:"
eu_dsn "$SENTRY_DSN_WEB" || die "That is not an https DSN on *.de.sentry.io. Check you are on the EU site."
step "Create project 2: Create Project. Platform: JavaScript or Deno. Name: stamina-api."
step "Again Settings → Client Keys (DSN) → copy the DSN."
ask SENTRY_DSN_API "Paste the stamina-api DSN:"
eu_dsn "$SENTRY_DSN_API" || die "That is not an https DSN on *.de.sentry.io."
write_env SENTRY_DSN_WEB "$SENTRY_DSN_WEB"
write_env SENTRY_DSN_API "$SENTRY_DSN_API"
set_var SENTRY_DSN_WEB "$SENTRY_DSN_WEB"
set_var SENTRY_DSN_API "$SENTRY_DSN_API"
note "DSNs are public identifiers, so they are GitHub variables, not secrets."

# ── 2. Merge the ticket 02 PR ─────────────────────────────────────────────
stage "GitHub: merge the ticket 02 pull request"
pr_state=$(gh pr view 2 --json state --jq .state 2>/dev/null || echo UNKNOWN)
case "$pr_state" in
  MERGED) say "PR #2 is already merged." ;;
  OPEN)
    say "Every check on PR #2 was green when this wizard was written."
    say "Merging puts release-please on main, which will open the first release PR."
    flush_stdin
    confirm "Squash-merge PR #2 now?" || die "Stopped before merging."
    gh pr merge 2 --squash --delete-branch ;;
  *) die "PR #2 is $pr_state; nothing to merge." ;;
esac
git switch main >/dev/null 2>&1 && git pull --ff-only >/dev/null 2>&1 || warn "could not update local main; run git pull yourself"

# ── 3. First release ──────────────────────────────────────────────────────
stage "First release: release-please PR → production deploy"
say "release-please opens a release PR a minute or so after the merge."
release_pr=""
for i in $(seq 1 18); do
  release_pr=$(gh pr list --state open --label "autorelease: pending" --json number --jq '.[0].number // empty')
  [[ -n "$release_pr" ]] && break
  note "waiting for the release PR ($i/18)"
  sleep 10
done
if [[ -z "$release_pr" ]]; then
  say "No open release PR. Either a release already happened or release-please failed."
  say "Check: gh run list --workflow release.yml --limit 3"
else
  say "Release PR #${release_pr}: $(gh pr view "$release_pr" --json title --jq .title)"
  say "Merging it tags the release, migrates the production database, deploys the API, then the web app, then smoke-tests."
  flush_stdin
  confirm "Merge release PR #${release_pr} (this deploys to production)?" || die "Stopped before the release."
  gh pr merge "$release_pr" --squash
  sleep 15
  run_id=$(gh run list --workflow release.yml --branch main --limit 1 --json databaseId --jq '.[0].databaseId')
  gh run watch "$run_id" --exit-status || die "The release run failed. Open: gh run view $run_id --log-failed"
fi
PROD_API_URL=$(gh variable get PROD_API_URL)
PROD_WEB_URL=$(gh variable get PROD_WEB_URL)
wait_for_health "$PROD_API_URL" || die "$PROD_API_URL/health never answered 200."
say "Production API healthy: $PROD_API_URL"
[[ "$(curl -s -o /dev/null -w '%{http_code}' "$PROD_WEB_URL" || true)" == 200 ]] || die "$PROD_WEB_URL did not answer 200."
say "Production web up: $PROD_WEB_URL"

# ── 4. UptimeRobot ────────────────────────────────────────────────────────
stage "UptimeRobot: check /health every 5 minutes and email you"
open_url "https://uptimerobot.com/signUp"
step "Sign up (free plan, no card) and confirm your email."
open_url "https://dashboard.uptimerobot.com/integrations"
step "Open Integrations & API → API → create a Main API key and copy it."
note "If the page differs, look for 'API' under Integrations in the UptimeRobot dashboard."
ask ALERT_EMAIL "Email address that should receive downtime alerts:"
ask_secret UPTIMEROBOT_API_KEY "Paste the UptimeRobot API key:"
write_env ALERT_EMAIL "$ALERT_EMAIL"
write_env UPTIMEROBOT_API_KEY "$UPTIMEROBOT_API_KEY"
write_env PROD_API_URL "$PROD_API_URL"
./scripts/ops/uptimerobot-setup.sh || die "uptimerobot-setup.sh failed; read the message above."
step "Optional: install the UptimeRobot mobile app and sign in to get push alerts too."

# ── 5. Brevo ──────────────────────────────────────────────────────────────
stage "Brevo: EU email sender for sign-in codes (used in ticket 04)"
open_url "https://www.brevo.com/"
step "Sign up (free plan, EU servers, no card) and confirm your email."
open_url "https://app.brevo.com/settings/keys/api"
step "SMTP & API → API Keys → Generate a new API key named 'stamina' and copy it."
ask SENDER_EMAIL "Sender address for sign-in emails (an address you can receive mail on):"
ask_secret BREVO_API_KEY "Paste the Brevo API key:"
write_env SENDER_EMAIL "$SENDER_EMAIL"
write_env BREVO_API_KEY "$BREVO_API_KEY"
./scripts/ops/brevo-setup.sh || die "brevo-setup.sh failed; read the message above."
note "Brevo will email you to verify the sender address. Domain authentication waits for a domain."

SKIPPED+=("Cloudflare R2: backups, restore test and OpenTofu state (ticket 02 boxes 1 and 3)")
SKIPPED+=("EUR 5 budget alert on every account that holds a card (none yet, see docs/infra.md)")
finish
}

run_wizard "$@"; exit
